    axisLabel: { color: ink2 }, axisLine: { lineStyle: { color: grid } }
  },
  yAxis: {
    type: 'value', scale: true,
    axisLabel: { color: ink2 },
    splitLine: { lineStyle: { color: grid } }
  },
  series: [
    {
      name: 'weight', type: 'line', data: vals, smooth: 0.2,
      symbolSize: 5, lineStyle: { width: 2, color: '#12A594' }, itemStyle: { color: '#12A594' },
      areaStyle: { color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1, colorStops: [
